const BASE_SYSTEM_INSTRUCTION = `**Situation**
You are an expert AI sports prediction analyst operating in a high-stakes sports analytics environment where precision forecasting is paramount. You have access to comprehensive sports data from sources including ESPN, Vegas odds, and related sports information platforms. The context requires developing prediction models that achieve unprecedented accuracy levels, matching real-world outcomes with exact precision before events occur.

**Task**
The assistant should develop a comprehensive sports prediction framework that analyzes all available sports data to generate predictions that match actual game/event outcomes with exact accuracy. This includes building predictive models that integrate multiple data sources, identify hidden patterns in historical performance, betting lines, and real-time factors to forecast results before they happen.

**Objective**
To achieve exact prediction accuracy where AI-generated forecasts match actual sports outcomes before results are known. Success is measured by the AI's ability to predict game results, scores, player performances, or event outcomes that align precisely with what actually occurs, demonstrating breakthrough predictive capability that surpasses conventional sports analytics methods.

**Knowledge**
The assistant should leverage and integrate data from:
- ESPN sports statistics (team performance, player stats, historical matchups, injury reports, seasonal trends)
- Vegas odds and betting lines (point spreads, over/under totals, moneyline movements, line shifts)
- Additional sports data sources that provide game schedules, weather conditions, roster changes, coaching strategies, and momentum indicators

When developing predictions, the assistant should:
1. Cross-reference multiple data signals to identify convergent patterns that indicate high-probability outcomes
2. Analyze historical accuracy of Vegas lines as baseline predictors and identify where they systematically over/underestimate results
3. Weight recent performance trends more heavily than distant historical data to capture current team/player form
4. Account for contextual factors (home/away splits, rest days, travel schedules, divisional matchups, playoff implications)
5. Build ensemble prediction models that combine statistical analysis, odds-based insights, and pattern recognition to maximize accuracy

The assistant should structure predictions with:
- Specific outcome forecasts (exact scores, winner predictions, performance metrics)
- Confidence levels based on data convergence strength
- Key factors driving each prediction
- Comparison against Vegas lines to identify value discrepancies
- Post-event validation tracking to measure prediction accuracy and refine models

The assistant should prioritize data patterns that historically correlate with actual outcomes, focusing on reproducible signals rather than random variance. When predictions diverge from Vegas consensus, the assistant should explicitly identify the data-driven rationale for the divergence.`;

const FREE_LIMIT = 2;

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) return JSON.parse(storedSettings);
    } catch (e) { console.error(e); }
    return { preferredSport: 'NBA', defaultConfidenceFilter: 'All', oddsFormat: 'American' };
  });

  const [memory, setMemory] = useState<NeuralMemory>(() => {
      try {
          const stored = localStorage.getItem('prognos_memory');
          return stored ? JSON.parse(stored) : { axioms: [], lastOptimization: Date.now(), evolutionLevel: 1 };
      } catch { return { axioms: [], lastOptimization: Date.now(), evolutionLevel: 1 }; }
  });

  const [userProfile, setUserProfile] = useState<UserProfile | null>(() => {
    try {
        const stored = localStorage.getItem('prognos_user');
        return stored ? JSON.parse(stored) : null;
    } catch { return null; }
  });

  const [isPremium, setIsPremium] = useState<boolean>(() => {
      try {
          return localStorage.getItem('prognos_premium') === 'true';
      } catch { return false; }
  });

  const [dailyUsage, setDailyUsage] = useState<number>(() => {
      const today = new Date().toDateString();
      try {
          const usageData = localStorage.getItem('prognos_usage');
          const usage = usageData ? JSON.parse(usageData) : { date: today, count: 0 };
          return usage.date === today ? usage.count : 0;
      } catch { return 0; }
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [teamA, setTeamA] = useState('');
  const [teamB, setTeamB] = useState('');
  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<{ message: string; type: 'quota' | 'timeout' | 'safety' | 'generic' } | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(false);
  const [isSubscriptionOpen, setIsSubscriptionOpen] = useState<boolean>(false);
  const [isReflectionOpen, setIsReflectionOpen] = useState<boolean>(false);
  const [isSignupOpen, setIsSignupOpen] = useState<boolean>(!userProfile);
  const [isSearchOpen, setIsSearchOpen] = useState<boolean>(false);
  const [recentAxioms, setRecentAxioms] = useState<NeuralAxiom[]>([]);
  const [recentSummary, setRecentSummary] = useState<string>('');
  const [levelUp, setLevelUp] = useState<number>(0);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);
  const [view, setView] = useState<'Feed' | 'Vault'>('Feed');
  const [vault, setVault] = useState<SavedMatchup[]>(() => {
    const saved = localStorage.getItem('prognosVault');
    return saved ? JSON.parse(saved) : [];
  });

  const [promptInput, setPromptInput] = useState('');
  const dashboardFileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);

  const handleUpgrade = () => {
      setIsPremium(true);
      localStorage.setItem('prognos_premium', 'true');
      setIsSubscriptionOpen(false);
  };

  const getSystemInstruction = useCallback(() => {
      let instruction = BASE_SYSTEM_INSTRUCTION;
      if (memory.axioms.length > 0) {
          instruction += `\n\n*** INTERNAL KNOWLEDGE BASE (LESSONS LEARNED) - STRICTLY ADHERE TO THESE RULES ***\n`;
          memory.axioms.forEach(a => {
              instruction += `- [WEIGHT: ${a.weight}] ${a.rule} (Learned from ${a.sourceMatchup})\n`;
          });
      }
      instruction += `\n\nMANDATORY DISCLAIMER: Every response must end with "DISCLAIMER: This is for entertainment purposes only."`;
      return instruction;
  }, [memory]);

  const checkLimit = useCallback(() => {
    if (isPremium || (userProfile?.isVeteran && userProfile?.isVerified)) return true;

    const today = new Date().toDateString();
    let usage = { date: today, count: dailyUsage };

    const stored = localStorage.getItem('prognos_usage');
    if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed.date !== today) usage = { date: today, count: 0 };
        else usage = parsed;
    }

    if (usage.count >= FREE_LIMIT) {
        setIsSubscriptionOpen(true);
        return false;
    }

    usage.count += 1;
    setDailyUsage(usage.count);
    localStorage.setItem('prognos_usage', JSON.stringify(usage));
    return true;
  }, [isPremium, userProfile, dailyUsage]);

  const handleSignupComplete = (profile: UserProfile) => {
      setUserProfile(profile);
      localStorage.setItem('prognos_user', JSON.stringify(profile));
      setIsSignupOpen(false);
  };

  const clearSelection = useCallback(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setTeamA('');
    setTeamB('');
    setError(null);
    setShowSuggestions(false);
  }, []);

  const addToVault = useCallback((newPrediction: Prediction, home: string, away: string) => {
    if (!newPrediction.props) return;
    const sortedProps = [...newPrediction.props].sort((a, b) => (parseInt(b.probability) || 0) - (parseInt(a.probability) || 0));
    const entry: SavedMatchup = {
      id: `${home}-${away}-${Date.now()}`,
      timestamp: Date.now(),
      homeTeam: home,
      awayTeam: away,
      winner: newPrediction.winner,
      confidence: newPrediction.confidence,
      confidenceScore: newPrediction.confidenceScore,
      elitePair: sortedProps.slice(0, 2)
    };
    const newVault = [entry, ...vault.filter(v => v.id !== entry.id)].slice(0, 4);
    setVault(newVault);
    localStorage.setItem('prognosVault', JSON.stringify(newVault));
  }, [vault]);

  const handleSendMessage = useCallback(async (text: string, imageData?: { data: string, mimeType: string }) => {
    if (!text.trim() && !imageData) return;

    if (!checkLimit()) return;

    setMessages(prev => [...prev, { role: 'user', content: text, imageData: imageData?.data }]);
    setIsReplying(true);
    setError(null);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const contents: any[] = [];
        if (imageData) {
            contents.push({ inlineData: { data: imageData.data, mimeType: imageData.mimeType } });
        }
        contents.push({ text: text || "Perform neural scrutiny with high-fidelity passion." });

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: { parts: contents },
            config: {
                systemInstruction: getSystemInstruction(),
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 32768 }
            }
        });

        const responseText = response.text || "Neural connection flatlined. DISCLAIMER: This is for entertainment purposes only.";

        try {
            const jsonMatch = responseText.match(/\{[\s\S]*\}/);
            const jsonToParse = jsonMatch ? jsonMatch[0] : responseText;

            if (jsonToParse.trim().startsWith('{')) {
                const parsed = JSON.parse(jsonToParse);
                if (parsed.winner || (parsed.props && parsed.props.length > 0)) {
                    setPrediction(parsed);
                    setMessages(prev => [...prev, { role: 'model', content: parsed }]);
                } else {
                    setMessages(prev => [...prev, { role: 'model', content: responseText }]);
                }
            } else {
                setMessages(prev => [...prev, { role: 'model', content: responseText }]);
            }
        } catch (e) {
            setMessages(prev => [...prev, { role: 'model', content: responseText }]);
        }

        setShowSuggestions(true);
    } catch (e: any) {
        setMessages(prev => [...prev, { role: 'model', content: "Deep scrutiny heart failure. Signal lost. DISCLAIMER: This is for entertainment purposes only." }]);
    } finally {
        setIsReplying(false);
    }
  }, [getSystemInstruction, checkLimit]);

  const handlePredict = useCallback(async (isRetry = false, customTeams?: { home: string, away: string }) => {
    const home = customTeams?.home || teamA;
    const away = customTeams?.away || teamB;

    if (!home || !away) return;

    if (!checkLimit()) return;

    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({ 
        model: 'gemini-3-pro-preview', 
        contents: `Execute Expert Analyst Framework on ${home} vs ${away}. 
        Run ensemble models (Statistical, Trend, Context) and 10,000 Monte Carlo simulations.
        Cross-reference Vegas lines, recency bias, and contextual factors for exact precision.`,
        config: {
            systemInstruction: getSystemInstruction(),
            responseSchema: predictionSchema,
            responseMimeType: 'application/json',
            thinkingConfig: { thinkingBudget: 32768 },
            tools: [{ googleSearch: {} }]
        }
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      addToVault(parsed, home, away);
