const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 5): Promise<T> {
  let delay = 2000;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      const errorStr = JSON.stringify(error).toLowerCase();
      const message = error.message?.toLowerCase() || "";
      const status = error?.status;

      // Explicitly check for 429 Resource Exhausted
      const isQuota = status === 429 || errorStr.includes('429') || errorStr.includes('resource_exhausted');

      // Check for RPC/Network/XHR errors (Common with proxy/unstable connections)
      const isTransient = 
        status === 500 || 
        status === 503 ||
        status === 504 ||
        message.includes('rpc failed') || 
        message.includes('xhr error') || 
        message.includes('fetch failed') ||
        errorStr.includes('500') ||
        errorStr.includes('deadline_exceeded') ||
        errorStr.includes('internal error') ||
        errorStr.includes('unknown') ||
        errorStr.includes('rpc failed');

      if ((isTransient || isQuota) && i < maxRetries - 1) {
        const backoff = isQuota ? delay * 3 : delay; // Aggressive backoff for quota
        console.warn(`PRO-N-OS: ${isQuota ? 'Quota limit' : 'Neural Uplink'} interference (${message || 'Unknown'}). Attempting resync ${i + 1}/${maxRetries} in ${backoff}ms...`);
        await new Promise(resolve => setTimeout(resolve, backoff));
        delay *= 1.5; 
        continue;
      }
      throw error;
    }
  }
  return await fn();
}

