export const PredictionDisplay: React.FC<PredictionDisplayProps> = memo(({ prediction, pickSlip = [], onTogglePick }) => {
  const [isSpeaking, setIsSpeaking] = useState(false);
  const confidenceStyle = confidenceStyles[prediction.confidence || 'Medium'] || confidenceStyles['Medium'];
  const rawScore = (prediction.confidenceScore != null) ? (prediction.confidenceScore > 1 ? prediction.confidenceScore / 100 : prediction.confidenceScore) : 0.5;
  const probVal = Math.round(rawScore * 100);

  const filteredProps = useMemo(() => {
    if (!prediction.props) return [];
    return [...prediction.props].sort((a, b) => (parseInt(b.probability || '0') || 0) - (parseInt(a.probability || '0') || 0));
  }, [prediction.props]);

  useEffect(() => {
      return () => {
          window.speechSynthesis.cancel();
      };
  }, []);

  const handleSpeak = () => {
    if (isSpeaking) {
        window.speechSynthesis.cancel();
        setIsSpeaking(false);
        return;
    }

    const text = `
        Neural Signal Report. 
        Projected Winner: ${prediction.winner}.
        Confidence Level: ${prediction.confidence}.
        Analysis: ${prediction.analysis}.
        Roster Stability: ${prediction.calibrationMetrics?.rosterStability} percent.
        Variance Risk: ${prediction.calibrationMetrics?.varianceRisk}.
    `;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.onend = () => setIsSpeaking(false);

    const voices = window.speechSynthesis.getVoices();
    const preferredVoice = voices.find(v => v.name.includes('English') && !v.name.includes('Microsoft')) || voices[0];
    if (preferredVoice) utterance.voice = preferredVoice;

    window.speechSynthesis.speak(utterance);
    setIsSpeaking(true);
  };

  return (
    <div className="space-y-10 w-full animate-fade-in pb-12 relative z-10">

       {/* Confidence & Neural Heartbeat Card */}
       <div className={`bg-zinc-950/80 backdrop-blur-3xl rounded-[4rem] border-2 ${confidenceStyle.border} ${confidenceStyle.glow} overflow-hidden p-10 relative tactical-outline scanline-sweep`}>
            <CardAccent />
            <div className="flex flex-col xl:flex-row gap-12 justify-between items-center relative z-10">
                <div className="flex-1 space-y-8 w-full">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4">
                             <div className="w-14 h-14 rounded-[1.5rem] bg-amber-500/10 flex items-center justify-center border-2 border-amber-500/40 shadow-[0_0_20px_rgba(245,158,11,0.15)]">
                                <LogoIcon className="w-7 h-7 text-amber-500" />
                             </div>
                             <div>
                                <h3 className="text-sm font-black text-white uppercase tracking-[0.5em] italic">NEURAL LOCK</h3>
                                <span className="text-[9px] font-black text-amber-500/60 uppercase tracking-[0.3em]">Synapse Sync Active</span>
                             </div>
                        </div>

                        <button 
                            onClick={handleSpeak}
                            className={`flex items-center gap-2 px-4 py-2 rounded-xl border transition-all ${
                                isSpeaking 
                                ? 'bg-amber-500 text-black border-amber-500 animate-pulse' 
                                : 'bg-black/40 text-zinc-400 border-zinc-800 hover:text-white hover:border-amber-500/50'
                            }`}
                        >
                            {isSpeaking ? <StopCircleIcon className="w-5 h-5" /> : <SpeakerWaveIcon className="w-5 h-5" />}
                            <span className="text-[9px] font-black uppercase tracking-widest hidden sm:block">
                                {isSpeaking ? 'Stop Signal' : 'Audio Report'}
                            </span>
                        </button>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                         <div className="bg-black/40 p-5 rounded-[2rem] border-2 border-white/5 tactical-outline">
                            <span className="text-[9px] font-black text-zinc-600 uppercase block mb-2 tracking-widest">Neural Heartbeat</span>
                            <span className={`text-lg font-black italic ${confidenceStyle.text}`}>{prediction.calibrationMetrics?.rosterStability ?? '--'}%</span>
                         </div>
                         <div className="bg-black/40 p-5 rounded-[2rem] border-2 border-white/5 tactical-outline">
                            <span className="text-[9px] font-black text-zinc-600 uppercase block mb-2 tracking-widest">Veto Variance</span>
                            <span className="text-lg font-black text-white italic">{prediction.calibrationMetrics?.varianceRisk ?? '--'}</span>
                         </div>
                    </div>

                    {prediction.vetoPhaseReport && (
                        <div className="bg-black/40 p-6 rounded-[2.5rem] border-2 border-red-500/30 shadow-[0_0_30px_rgba(239,68,68,0.1)]">
                            <div className="flex items-center gap-2 mb-2">
                                <span className="text-[9px] font-black text-red-500 uppercase tracking-widest">Neural Disruption Detected</span>
                            </div>
                            <p className="text-xs text-zinc-300 font-medium italic leading-relaxed">"{prediction.vetoPhaseReport}"</p>
                        </div>
                    )}
                </div>

                <div className="relative flex items-center justify-center w-60 h-60 flex-shrink-0">
                    <svg className="w-full h-full transform -rotate-90 filter drop-shadow-[0_0_15px_rgba(245,158,11,0.2)]">
                        <circle cx="120" cy="120" r="100" stroke="currentColor" strokeWidth="16" fill="transparent" className="text-zinc-900" />
                        <circle 
                          cx="120" cy="120" r="100" 
                          stroke="currentColor" strokeWidth="16" 
                          fill="transparent" strokeDasharray={628} 
                          strokeDashoffset={628 - (628 * probVal) / 100} 
                          className={`${confidenceStyle.text} transition-all duration-[1500ms] ease-out`} 
                          strokeLinecap="round"
                        />
                    </svg>
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                        <span className="text-7xl font-black text-white tabular-nums tracking-tighter italic drop-shadow-[0_0_10px_rgba(255,255,255,0.3)]">{probVal}%</span>
                        <span className="text-[11px] font-black text-zinc-500 uppercase tracking-[0.6em] mt-2">{prediction.confidence} SIGNAL</span>
                    </div>
                    <div className={`absolute inset-0 border-4 ${confidenceStyle.border} rounded-full animate-ping opacity-20 pointer-events-none`}></div>
                </div>

                <div className="flex-1 flex justify-center w-full">
                    <NeuralRadarChart metrics={prediction.calibrationMetrics} />
                </div>
            </div>
       </div>

       {prediction.winner && (
        <div className={`p-12 rounded-[5rem] border-4 ${confidenceStyle.border} bg-zinc-950/90 shadow-2xl relative overflow-hidden art-border-glow tactical-outline scanline-sweep`}>
          <div className="flex flex-col md:flex-row items-center gap-12 relative z-10">
                <div className="relative group">
                  <div className="absolute -inset-6 bg-amber-500/30 blur-3xl opacity-0 group-hover:opacity-100 transition-opacity duration-700"></div>
                  <img 
                    src={`https://avatar.vercel.sh/${encodeURIComponent(prediction.winner)}.png?size=240`} 
                    className={`w-52 h-52 rounded-[3.5rem] border-4 ${confidenceStyle.border} shadow-2xl relative z-10 transform transition-transform group-hover:rotate-3 group-hover:scale-105 duration-500`} 
                    alt="Team Logo"
                  />
                </div>
                <div className="space-y-4 text-center md:text-left w-full">
                    <span className="text-[14px] font-black uppercase tracking-[0.8em] text-amber-500 block mb-3 italic">Kinetic Masterpiece Outcome</span>
                    <h2 className="text-6xl md:text-9xl font-black text-white leading-none tracking-tighter uppercase italic">{prediction.winner}</h2>

                    {prediction.statComparison && prediction.statComparison.length > 0 && (
                        <StatComparisonGrid stats={prediction.statComparison} homeTeam="HOME" awayTeam="AWAY" />
                    )}
                </div>
          </div>

          {prediction.keyMatchups && prediction.keyMatchups.length > 0 && (
            <PlayerMatchupTable 
                matchups={prediction.keyMatchups} 
                homeTeam={prediction.homeTeam || "HOME"} 
                awayTeam={prediction.awayTeam || "AWAY"} 
            />
          )}

          <div className="mt-14 grid md:grid-cols-2 gap-8 relative z-10">
             {prediction.ensembleModel && <EnsembleDisplay model={prediction.ensembleModel} />}
             {prediction.simulatedScenarios && <SimulationDisplay sim={prediction.simulatedScenarios} winner={prediction.winner} />}
          </div>

          {prediction.analysis && (
            <div className="mt-14 pt-12 border-t border-white/5 relative z-10">
                <p className="text-zinc-200 text-2xl leading-relaxed font-bold italic border-l-4 border-amber-500/50 pl-10 shadow-sm">
                  "{prediction.analysis}"
                </p>
            </div>
          )}
        </div>
       )}

       {filteredProps.length > 0 && (
         <div className="space-y-10">
            <div className="flex items-center gap-4 px-6">
                <h3 className="text-[14px] font-black text-zinc-600 uppercase tracking-[0.8em] italic">Elite Prop Scrutiny Stream</h3>
                <div className="h-px flex-1 bg-zinc-900"></div>
            </div>
            <div className="grid gap-8">
                {filteredProps.map((prop, index) => {
                    const isInSlip = pickSlip.some(p => p.player === prop.player && p.stat === prop.stat);
                    return (
                        <div key={index} className={`bg-zinc-950/70 backdrop-blur-xl rounded-[4rem] border-2 p-10 transition-all duration-500 hover:scale-[1.02] ${isInSlip ? 'border-amber-500 shadow-[0_0_50px_rgba(245,158,11,0.2)]' : 'border-zinc-900 hover:border-zinc-700'} tactical-outline relative overflow-hidden`}>
                            <div className="flex flex-col md:flex-row items-start md:items-center gap-10 mb-8">
                                <img src={`https://avatar.vercel.sh/${encodeURIComponent(prop.player)}.png?size=120`} className="w-24 h-24 rounded-[2rem] border-2 border-zinc-800 shadow-xl" alt={prop.player} />
                                <div className="flex-1 text-center md:text-left w-full">
                                    <span className="text-3xl font-black text-white uppercase italic tracking-tighter block mb-4">{prop.player}</span>

                                    <div className="flex flex-wrap justify-center md:justify-start items-center gap-8">
                                        <div className="flex flex-col items-center md:items-start">
                                            <span className="text-[8px] font-black text-zinc-600 uppercase tracking-widest mb-1">Target</span>
                                            <div className="flex items-baseline gap-2">
                                                <span className={`text-xl font-black tracking-widest ${prop.type === 'MORE' ? 'text-green-400' : 'text-rose-500'}`}>{prop.type}</span>
                                                <span className="text-5xl font-black text-white tabular-nums tracking-tighter">{prop.line}</span>
                                            </div>
                                            <span className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em] mt-1">{prop.stat}</span>
                                        </div>

                                        {prop.projectedValue && (
                                            <>
                                                <div className="w-px h-12 bg-zinc-800 hidden md:block"></div>
                                                <div className="flex flex-col items-center md:items-start">
                                                     <span className="text-[8px] font-black text-zinc-600 uppercase tracking-widest mb-1">Neural Projection</span>
                                                     <span className="text-4xl font-black text-amber-500 tabular-nums tracking-tighter italic">
                                                        {prop.projectedValue}
                                                     </span>
                                                </div>
                                            </>
                                        )}
                                    </div>

                                    {prop.projectionData && (
                                      <div className="mt-8 bg-black/40 border border-zinc-800 rounded-2xl p-4 flex flex-col md:flex-row gap-4 items-center justify-between w-full max-w-2xl">
                                         <div className="flex gap-4 items-center">
                                            <div className="text-center">
                                              <div className="text-[7px] font-black text-zinc-600 uppercase tracking-wider">L5 Avg</div>
                                              <div className="text-sm font-bold text-white tabular-nums">{prop.projectionData.last5Average}</div>
                                            </div>
                                            <div className="w-px h-6 bg-zinc-800"></div>
                                            <div className="text-center">
                                              <div className="text-[7px] font-black text-zinc-600 uppercase tracking-wider">L10 Avg</div>
                                              <div className="text-sm font-bold text-white tabular-nums">{prop.projectionData.last10Average}</div>
                                            </div>
                                            <div className="w-px h-6 bg-zinc-800"></div>
                                            <div className="text-center">
                                              <div className="text-[7px] font-black text-zinc-600 uppercase tracking-wider">Season</div>
                                              <div className="text-sm font-bold text-amber-500 tabular-nums">{prop.projectionData.seasonAverage}</div>
                                            </div>
                                         </div>

                                         <div className="flex-1 w-full space-y-2">
                                            <div className="flex justify-between text-[7px] font-black text-zinc-600 uppercase tracking-widest">
                                               <span>Floor: {prop.projectionData.floor}</span>
                                               <span>Ceiling: {prop.projectionData.ceiling}</span>
                                            </div>
                                            <div className="h-1.5 w-full bg-zinc-900 rounded-full overflow-hidden">
                                               <div className="h-full bg-gradient-to-r from-zinc-700 via-amber-600 to-amber-500 w-[70%] ml-[15%] rounded-full opacity-60"></div>
                                            </div>
                                         </div>
                                      </div>
                                    )}
                                </div>
                                <button 
                                    onClick={() => onTogglePick && onTogglePick(prop)} 
                                    className={`w-16 h-16 rounded-3xl flex items-center justify-center transition-all flex-shrink-0 ${isInSlip ? 'bg-amber-500 text-black shadow-xl shadow-amber-500/30 rotate-0' : 'bg-zinc-900 text-zinc-600 border-2 border-zinc-800 hover:text-amber-500 hover:border-amber-500/40 rotate-12'}`}
                                >
                                    {isInSlip ? <CheckIcon className="w-8 h-8" /> : <PlusIcon className="w-8 h-8" />}
                                </button>
                            </div>

                            {prop.matchupDeltas && prop.matchupDeltas.length > 0 && (
                                <div className="mb-6 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                                    {prop.matchupDeltas.map((delta, dIdx) => (
                                        <div key={dIdx} className="bg-black/40 border border-zinc-800 rounded-xl p-3 flex justify-between items-center">
                                            <div>
                                                <span className="text-[9px] text-zinc-500 uppercase block tracking-wider">{delta.category}</span>
                                                <div className="text-[10px] font-bold text-white mt-0.5">
                                                    {delta.playerStat} vs {delta.opponentStat}
                                                </div>
                                            </div>
                                            <div className={`text-[8px] font-black uppercase px-2 py-1 rounded-lg ${
                                                delta.advantage === 'Player' ? 'bg-green-500/20 text-green-500' :
                                                delta.advantage === 'Opponent' ? 'bg-red-500/20 text-red-500' : 'bg-zinc-800 text-zinc-500'
                                            }`}>
                                                {delta.advantage === 'Player' ? 'ADV' : delta.advantage === 'Opponent' ? 'DIS' : 'PUSH'}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}

                            {prop.analysis && (
                                <div className="border-t border-white/5 pt-6">
                                    <p className="text-zinc-400 text-sm leading-relaxed italic">
                                        "{prop.analysis}"
                                    </p>
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
         </div>
       )}
    </div>
  );
});
